SELECT DISTINCT o.id, o.customer_name, o.status, o.pay_method, o.user_grade, o.created_at
FROM demo_orders o
LEFT JOIN demo_order_items i ON i.order_id = o.id
WHERE o.created_at >= #{orderDate}
  AND o.created_at < #{orderDateEnd}

    AND i.quantity >= #{minQuantity}

ORDER BY o.id

SELECT DISTINCT o.id, o.customer_name, o.status, o.pay_method, o.user_grade, o.created_at
FROM demo_orders o
LEFT JOIN demo_order_items i ON i.order_id = o.id
WHERE o.created_at >= #{fromDate}
  AND o.created_at < #{toDateEnd}

    AND i.quantity >= #{minQuantity}

ORDER BY o.id

SELECT DISTINCT o.id, o.customer_name, o.status, o.pay_method, o.user_grade, o.created_at
